code.C:
#include <stdio.h>

int main() {
    long long n;
    if (scanf("%lld", &n) == 1) {
        int cnt = 0;
        for (long long i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                cnt++;
                if (i * i != n) cnt++;
            }
        }
        printf("%d\n", cnt);
    }
    return 0;
}

